// ============================================
// the AI service WhatsApp Agent — Message Parser (reused from Gateway v3.3 / agent v0.2)
// ============================================
// LAYER 1: Filter out non-message events BEFORE any DB call.
// UNCHANGED from v0.2 for regression safety.
// ============================================

try {
  const raw = $input.item.json.body || $input.item.json;

  let messageId = '';
  if (raw.data && raw.data.messages && raw.data.messages.key) {
    messageId = raw.data.messages.key.id || '';
  }

  let phone = '';
  let rawMessage = '';
  let isFromMe = false;
  let eventType = '';
  let hasImage = false;
  let imageData = null;
  let unsupportedMedia = null;

  if (raw.event) {
    eventType = raw.event;
  }

  // FIXED 2026-08-13 (found live: welcome menus were going out to people who
  // had never messaged us -- unsolicited outbound, the kind of pattern that
  // gets a WhatsApp number banned). This check was `if (eventType && ...)`,
  // so a payload with NO event field skipped the guard entirely and got
  // parsed as a customer message. Now fail-closed: no recognized event type,
  // no processing.
  const allowedEvents = ['messages.upsert', 'message', 'messages.received'];
  if (!eventType || !allowedEvents.includes(eventType.toLowerCase())) {
    return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
  }

  const sMsg = (raw.data && raw.data.messages) ? raw.data.messages : null;
  const sRemoteJid = (sMsg && sMsg.key && sMsg.key.remoteJid)
    || (sMsg && sMsg.remoteJid)
    || '';
  const sIsBroadcast = !!(sMsg && sMsg.broadcast === true);
  if (sRemoteJid === 'status@broadcast' || sIsBroadcast) {
    return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
  }
  // FIXED 2026-08-11 (found live via a raw execution payload): a group JID
  // ("<creatorNumber>-<groupId>@g.us") was being stripped of "@g.us" and
  // then having its hyphen stripped by the later [^0-9] scrub, concatenating
  // the creator's number and the group ID into one garbage ~23-digit fake
  // "phone" -- confirmed to exactly match the mangled numbers seen in
  // production (a spam/marketing group the bot's number is apparently a
  // member of). Every subsequent unrelated message from that same group then
  // collapsed into the SAME fake session, corrupting flow state and firing
  // duplicate handoff alerts. This bot is 1:1 customer service only (brief:
  // "One WhatsApp number, natural conversation") -- there is no product
  // requirement for group support, so any group message is skipped outright,
  // same as the existing status@broadcast filter above.
  if (sRemoteJid.endsWith('@g.us')) {
    return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
  }
  // FIXED 2026-08-11 (allowlist, not blocklist): the @g.us skip above stops
  // group chats, but WhatsApp also delivers privacy-LID JIDs ("<id>@lid" --
  // confirmed live in this environment on a group participant field),
  // channel/newsletter JIDs, and possibly future formats. Any of those would
  // hit the same digits-only scrub and mint another garbage fake "phone".
  // So: only process senders we can derive a REAL phone number for -- either
  // a standard individual JID (@s.whatsapp.net) or an explicit
  // cleanedSenderPn supplied by the WhatsApp gateway (which covers LID senders whose
  // real number the WhatsApp gateway has resolved). Everything else is skipped outright.
  if (sMsg) {
    const jidIsIndividual = /@s\.whatsapp\.net$/.test(sRemoteJid);
    const hasCleanPn = !!(sMsg.key && sMsg.key.cleanedSenderPn);
    if (!jidIsIndividual && !hasCleanPn) {
      return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
    }
  }

  if (raw.data && raw.data.messages) {
    const msg = raw.data.messages;
    // FIXED 2026-08-13: also honour a top-level fromMe. Reading only
    // key.fromMe meant any payload variant that puts the flag elsewhere
    // would be treated as inbound -- and echoing our OWN outbound messages
    // back through the bot is exactly how unsolicited replies get sent.
    if ((msg.key && msg.key.fromMe === true) || msg.fromMe === true) {
      isFromMe = true;
    }
    phone = (msg.key && msg.key.cleanedSenderPn)
      || (msg.key && msg.key.remoteJid
          ? msg.key.remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '')
          : '')
      || '';
    rawMessage = msg.messageBody
      || (msg.message && msg.message.conversation)
      || (msg.message && msg.message.extendedTextMessage && msg.message.extendedTextMessage.text)
      || '';

    if (msg.message && msg.message.imageMessage) {
      hasImage = true;
      imageData = {
        mimetype: msg.message.imageMessage.mimetype || '',
        caption: msg.message.imageMessage.caption || '',
        url: msg.message.imageMessage.url || '',
        mediaKey: msg.message.imageMessage.mediaKey || '',
        fileEncSha256: msg.message.imageMessage.fileEncSha256 || '',
        fileSha256: msg.message.imageMessage.fileSha256 || '',
        fileLength: msg.message.imageMessage.fileLength || 0
      };
      if (!rawMessage && imageData.caption) {
        rawMessage = imageData.caption;
      }
    }

    // ADDED 2026-08-11: non-text, non-image message types used to fall
    // through to the "no text, no image" skip below -- the customer got
    // DEAD SILENCE (indistinguishable from the bot being broken). Voice
    // notes especially are common in our markets. Captions on videos and
    // documents are treated as real text (same as image captions); anything
    // we genuinely can't read gets a warm "please type it" reply downstream
    // via the unsupportedMedia flag. Stickers are deliberately SILENT skips:
    // they're reactions, not questions, and answering one with "I can't
    // read that" would be noise.
    const mBody = msg.message || {};
    if (!rawMessage && !hasImage) {
      if (mBody.audioMessage) {
        unsupportedMedia = 'voice';
      } else if (mBody.videoMessage) {
        const vcap = (mBody.videoMessage.caption || '').trim();
        if (vcap) { rawMessage = vcap; } else { unsupportedMedia = 'video'; }
      } else if (mBody.documentMessage || mBody.documentWithCaptionMessage) {
        const docMsg = mBody.documentMessage
          || (mBody.documentWithCaptionMessage && mBody.documentWithCaptionMessage.message && mBody.documentWithCaptionMessage.message.documentMessage)
          || {};
        const dcap = (docMsg.caption || '').trim();
        if (dcap) { rawMessage = dcap; } else { unsupportedMedia = 'document'; }
      } else if (mBody.stickerMessage) {
        return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
      } else if (mBody.locationMessage || mBody.liveLocationMessage) {
        unsupportedMedia = 'location';
      } else if (mBody.contactMessage || mBody.contactsArrayMessage) {
        unsupportedMedia = 'contact';
      }
    }
  } else {
    // FIXED 2026-08-13: this used to fall back to
    // `phone = raw.phone || raw.from` / `rawMessage = raw.message || raw.text`
    // for any unrecognized payload shape. Because that path never populates
    // sMsg, it bypassed BOTH the fromMe check AND the @s.whatsapp.net/
    // cleanedSenderPn allowlist above -- so a delivery receipt, ack, or
    // outbound echo carrying a top-level phone/from field would be read as
    // an INBOUND customer message from the RECIPIENT's number, create a
    // session, and fire a first-contact welcome menu at someone who never
    // wrote to us. Every real the WhatsApp gateway inbound message arrives as
    // data.messages (verified against a captured production payload), so
    // anything else is now skipped outright.
    return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
  }

  phone = phone.replace(/[^0-9]/g, '');

  if (isFromMe) {
    // ADDED 2026\u002d08\u002d13: outbound messages used to be dropped outright. They
    // now go to the human\u002dtakeover check \u002d\u002d an outbound message whose text
    // we have NOT recorded as bot\u002dsent means a teammate replied by hand, and
    // the bot must get out of their way. NOTE: rawMessage is deliberately
    // read here BEFORE the 500\u002dchar truncation below, because the recorded
    // hash covers the full message and a quote reply is well over 500 chars.
    const outboundText = (rawMessage || '').trim();
    if (phone && phone.length >= 7 && outboundText) {
      return { json: { route: 'outbound_check', phone: phone, rawMessage: outboundText, message: '', hasImage: false, imageData: null, unsupportedMedia: null, messageId: messageId, contentKey: '' } };
    }
    return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
  }
  if (!phone || phone.length < 7) {
    return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
  }

  rawMessage = rawMessage.substring(0, 500).trim();

  if (!rawMessage && !hasImage && !unsupportedMedia) {
    return { json: { route: 'skip', phone: '', rawMessage: '', message: '', hasImage: false, imageData: null, messageId: '', contentKey: '' } };
  }

  // ADDED 2026-08-14 (the product owner Phase 1, step 2): a click-to-WhatsApp ad attaches
  // its details to the customer's FIRST message only, on contextInfo. It is
  // never resent, so anything not captured here is lost permanently. Present
  // on whichever message type carried the click, hence the sweep.
  let adSource = null;
  try {
    const mBody2 = (raw.data && raw.data.messages && raw.data.messages.message) || {};
    let ctxInfo = null;
    const carriers = ['extendedTextMessage', 'imageMessage', 'videoMessage', 'documentMessage', 'audioMessage'];
    for (const k of carriers) {
      if (mBody2[k] && mBody2[k].contextInfo) { ctxInfo = mBody2[k].contextInfo; break; }
    }
    if (!ctxInfo && mBody2.contextInfo) ctxInfo = mBody2.contextInfo;
    const ext = ctxInfo && ctxInfo.externalAdReply;
    if (ext || (ctxInfo && ctxInfo.conversionSource)) {
      adSource = {
        conversionSource: (ctxInfo && ctxInfo.conversionSource) || '',
        sourceApp: (ext && ext.sourceApp) || '',
        sourceId: (ext && ext.sourceId) || '',
        sourceUrl: (ext && ext.sourceUrl) || '',
        title: ((ext && ext.title) || '').substring(0, 300),
        body: ((ext && ext.body) || '').substring(0, 1000),
        ctwaClid: (ext && ext.ctwaClid) || ''
      };
      // Only worth a row if something identifies the ad.
      if (!adSource.sourceId && !adSource.ctwaClid && !adSource.conversionSource) adSource = null;
    }
  } catch (e) {
    adSource = null;
  }

  const message = (rawMessage || '').toUpperCase().trim();

  function hashStr(s) {
    let h1 = 0x811c9dc5;
    let h2 = 0x1000193;
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      h1 = (h1 ^ c) >>> 0;
      h1 = Math.imul(h1, 0x01000193) >>> 0;
      h2 = (h2 ^ c) >>> 0;
      h2 = Math.imul(h2, 0x01000193 + 7) >>> 0;
    }
    return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
  }
  // FIXED 2026-08-13 (found live): dedup used to key on a hash of the
  // message TEXT inside a 5-second window. the WhatsApp gateway re-delivers webhooks --
  // one customer question produced two differently-worded AI answers
  // seconds apart, and a later re-delivery produced a stray "I don't have
  // an answer for that" 31 minutes after the conversation had moved on.
  // WhatsApp's own message id is stable across every re-delivery of the
  // SAME message, so key on it whenever present and let the query widen
  // the window to match. Text hashing stays as the fallback for a payload
  // with no id, where a short window is still correct (a customer may
  // legitimately repeat themselves).
  const contentForHash = rawMessage || (hasImage ? 'IMG' : (unsupportedMedia ? unsupportedMedia + ':' + messageId : ''));
  const contentHash = hashStr(contentForHash);
  const dedupMode = messageId ? 'id' : 'hash';
  const contentKey = messageId ? (phone + ':id:' + messageId) : (phone + ':' + contentHash);

  return {
    json: {
      route: 'process',
      phone: phone,
      rawMessage: rawMessage,
      message: message,
      hasImage: hasImage,
      imageData: imageData,
      unsupportedMedia: unsupportedMedia,
      messageId: messageId,
      dedupMode: dedupMode,
      hasAdSource: !!adSource,
      adConversionSource: adSource ? adSource.conversionSource : '',
      adSourceApp: adSource ? adSource.sourceApp : '',
      adSourceId: adSource ? adSource.sourceId : '',
      adSourceUrl: adSource ? adSource.sourceUrl : '',
      adTitle: adSource ? adSource.title : '',
      adBody: adSource ? adSource.body : '',
      adCtwaClid: adSource ? adSource.ctwaClid : '',
      contentKey: contentKey
    }
  };

} catch (err) {
  return {
    json: {
      route: 'skip',
      phone: '',
      rawMessage: '',
      message: '',
      hasImage: false,
      imageData: null,
      messageId: '',
      contentKey: '',
      error: err.message
    }
  };
}

// LAYER 2 continued: Check dedup result (unchanged from v0.2)
const dedupResult = $input.all();
const parsed = $('Parse Message').first().json;

const firstResult = dedupResult && dedupResult[0] && dedupResult[0].json;

if (firstResult && firstResult.error) {
  return { json: { ...parsed } };
}

const isNew = firstResult && firstResult.id;

if (!isNew) {
  return { json: { ...parsed, route: 'duplicate' } };
}

return { json: { ...parsed } };

// Image received, NOT during the tracking flow. No the AI service call, no session touch, no log (unchanged from v0.2).
const parsed = $('Parse Message').first().json;
const IMAGE_REPLY =
  "Thanks for the photo! \ud83d\udcf7 Someone from our team will take a look "
  + "and get back to you shortly. In the meantime, feel free to ask if there's "
  + "anything else I can help with! \ud83d\ude0a";
return { json: { phone: parsed.phone, response: IMAGE_REPLY } };

// PRD §3.3 exact wording. No state change -- stays TRACKING_AWAITING_NUMBER,
// no attempts increment (this isn't a failed lookup, just unreadable input).
const dm = $('Decision Node').first().json;
const response = "We currently cannot read the Tracking No. directly from an image. If the goods were delivered by a Chinese courier, please find the courier tracking number, which is usually located near the barcode. If the goods were delivered by truck, please find the \"Tracking No.\" on the warehouse receipt issued by ACME. Please copy or type the Tracking No. and send it to us again.";
return { json: { phone: dm.phone, response } };

// ============================================================
// Decision Node — pre-the AI service-call routing (session-state based)
// ============================================================
// RECONSTRUCTED from CLAUDE.md's "Current state (v0.4)" description — no v0.4
// workflow JSON was committed to the repo, only db/migrations/001_*.sql.
// Verify this against the live n8n graph before importing wholesale.
//
// Applies the 30-min timeout reset, resolves cached-menu digit routing (brief
// §5a: "cache the mapping ... not calling for it on every digit"), defensively
// resets any unrecognized state (mirrors the Gateway's own "Defensive state
// reset" pattern -- never get permanently stuck), and picks which the AI service-
// calling lane handles this turn:
//   first_contact_menu | quote_flow | partner_flow | conversational
// (Human handoff has no persisted state of its own -- it's a one-turn action
// resolved inside the conversational lane's Classify Route / Quote Decision /
// Partner Decision, not a route picked here.)
// ============================================================

const parsed = $('Parse Message').first().json;
const row = $('Session Read').first().json;

// ADDED 2026\u002d08\u002d13: is a teammate currently handling this customer by hand?
// Fails OPEN (treats anything unexpected as "not paused") \u002d\u002d a bot that
// talks too much is a far smaller problem than a bot that goes permanently
// silent because a lookup misbehaved.
let isPaused = false;
try {
  const pauseRows = $('Pause Read').all();
  isPaused = pauseRows.some(r => r && r.json && r.json.paused_until && new Date(r.json.paused_until).getTime() > Date.now());
} catch (e) {
  isPaused = false;
}

const TIMEOUT_MINUTES = 30;
const VALID_STATES = ['MAIN_MENU', 'QUOTE_COLLECTING', 'QUOTE_CONFIRMING', 'PARTNER_COLLECTING', 'PARTNER_CONFIRMING', 'TRACKING_AWAITING_NUMBER'];

let isFirstContact = row.is_first_contact === true;
let state = row.current_state || 'MAIN_MENU';
let context = row.current_context;
if (typeof context === 'string') {
  try { context = JSON.parse(context); } catch (e) { context = {}; }
}
context = context || {};

if (!VALID_STATES.includes(state)) {
  state = 'MAIN_MENU';
  context = { menu: context.menu || null };
}

const minutesInactive = parseFloat(row.minutes_inactive) || 0;
let timedOut = false;
if (!isFirstContact && minutesInactive > TIMEOUT_MINUTES && state !== 'MAIN_MENU') {
  // Stale mid-flow state (quote/partner) older than 30 minutes is dropped.
  // Keep the cached menu mapping (it's static, no need to refetch).
  state = 'MAIN_MENU';
  context = { menu: context.menu || null };
  timedOut = true;
}

// Resolve a bare digit reply against the cached menu[] mapping instead of
// hardcoding "2 = quote" here (brief §5a) or re-calling firstContact just
// to re-fetch a static array.
let forcedIntent = null;
const trimmed = (parsed.rawMessage || '').trim();
if (/^[0-9]$/.test(trimmed) && Array.isArray(context.menu)) {
  const match = context.menu.find(m => String(m.number) === trimmed);
  if (match) forcedIntent = match.intent;
}

// Which extract schema to speculatively request on a COLD conversational-lane
// call (state MAIN_MENU, not yet in a flow). The API only supports one
// extract schema per call (brief §9: one call, no separate calls), so this
// picks between quote/partner ahead of knowing the classified intent. A digit
// press is unambiguous (no guess). Otherwise, a lightweight keyword check on
// the message decides -- NOT a guess at field VALUES (never guessed, per
// CLAUDE.md), just at which SCHEMA the same message should be parsed against.
// Defaults to quote, the more common cold-entry case. Worth revisiting if the
// API ever supports requesting both schemas in one call.
let speculativeExtract = 'quote';
if (forcedIntent === 'partner') {
  speculativeExtract = 'partner';
} else if (!forcedIntent) {
  const PARTNER_KEYWORDS = /\b(partner|reseller|wholesale|wholesaler|distributor|freight forwarder)\b/i;
  if (PARTNER_KEYWORDS.test(parsed.rawMessage || '')) {
    speculativeExtract = 'partner';
  }
}

let route;
if (isFirstContact) {
  route = 'first_contact_menu';
} else if (forcedIntent === 'human' || /^\s*(agent|human)\s*[.!]*$/i.test(trimmed)) {
  // ADDED 2026-08-11 (nav discoverability): the flows now ADVERTISE typing
  // "agent" to reach a person, so the bare word must work deterministically
  // from every state -- same guaranteed route as a digit-5 press, no NLU
  // confidence roll involved. Bare-word only ("agent", "Agent.", "human"):
  // a sentence like "I need an agent for customs" mid-quote is real flow
  // content and must NOT trigger this -- sentences stay with the normal
  // NLU/frustration checks.
  // FIXED 2026-08-01 (found by external code review, confirmed by reading
  // this exact if/else chain): a digit-5 press must reach a human from ANY
  // state. Previously state alone decided the route, so pressing 5 while
  // mid-quote/mid-partner/mid-tracking silently got swallowed as literal
  // input to whatever flow was active (e.g. treated as a bogus tracking
  // number, or stored as a deterministic-phase answer) -- the customer never
  // actually reached a human. This check must come before any state-based
  // branch below, not after.
  route = 'human_escape';
} else if (state === 'QUOTE_COLLECTING' || state === 'QUOTE_CONFIRMING') {
  route = 'quote_flow';
} else if (state === 'PARTNER_COLLECTING' && context.phase === 'deterministic') {
  // PRD §5.2 fields with no matching /ai/chat extraction slot (nationality,
  // primary_operating_market, existing_customer_resources, delivery/COD
  // capability, services_requested) are collected as plain sequential
  // questions once AI-extractable fields are done -- no API call needed,
  // n8n just stores the raw answer to whichever question is next.
  route = 'partner_deterministic';
} else if (state === 'PARTNER_COLLECTING' || state === 'PARTNER_CONFIRMING') {
  route = 'partner_flow';
} else if (state === 'TRACKING_AWAITING_NUMBER') {
  route = 'tracking_flow';
} else {
  route = 'conversational';
}

// FIXED 2026-07-31: a customer saying "hi" while the bot was waiting for a
// tracking number used to burn one of only 2 retry attempts on a doomed
// lookup ("no order found for 'hi'") -- greetings/exit-words never look
// like real tracking numbers (those are near-universally alphanumeric with
// digits), so recognize them here and exit back to the menu instead of
// wasting a retry.
let trackingExitSignal = false;
if (route === 'tracking_flow') {
  const trimmedMsg = (parsed.rawMessage || '').trim();
  const looksLikeGreetingOrExit = /^(hi|hello|hey|hola|sup|yo)\b/i.test(trimmedMsg) || /\b(cancel|stop|never ?mind|forget it|exit|quit|menu|main menu|start over)\b/i.test(trimmedMsg);
  const hasDigit = /\d/.test(trimmedMsg);
  trackingExitSignal = looksLikeGreetingOrExit && !hasDigit;
}

// FIXED 2026-08-11 (found live): a customer's tracking-retry input was
// forwarded to GET /orders/status/{id} completely unvalidated -- a bare
// "2" got sent verbatim and the backend's typo-tolerant matching returned a
// real but unrelated order instead of a 404 (a cross-customer data exposure
// risk, not just a wasted lookup). Anything too short to plausibly be a
// real tracking/order number is caught here, before the API is ever called.
// Computed here (not inside the IF node) per the documented n8n strict-type
// IF gotcha -- always compute a real boolean upstream.
let trackingFormatValid = true;
if (route === 'tracking_flow' && !trackingExitSignal) {
  const trimmedMsg = (parsed.rawMessage || '').trim();
  trackingFormatValid = trimmedMsg.length >= 5;
}

// ADDED 2026-08-21 (the engineer's suggestion): the moment a customer names their
// destination, show them the rates for it instead of making them finish the
// whole form first. Calvince spent 28 turns trying to get a number.
//
// Deliberately NO rates are stored in n8n. The question is folded into the
// /ai/chat call this turn ALREADY makes, so the knowledge base stays the
// single source of truth, there is no second 30-second API call to wait
// for, and a rate change by the product owner is picked up automatically.
//
// Fires only while destination_country is still unknown inside the quote
// flow -- which is precisely the turn after we asked "which country are you
// shipping to?", since that field is first in the ask order. Self-limiting:
// once the country is captured the condition can never be true again for
// this conversation, so nobody gets the rate card twice.
//
// The appended wording deliberately avoids the words "air" and "sea" and any
// numbers, so it cannot contaminate field extraction running on the same
// message.
let quoteRateProbe = false;
if (route === 'quote_flow') {
  const knownFields = (context && context.fields) || {};
  const probeMsg = (parsed.rawMessage || '').trim();
  const bareDigit = /^[0-9]$/.test(probeMsg);
  const fillerish = /^(hi|hello|hey|thanks|thank you|ok|okay|yes|no|sure)\b/i.test(probeMsg) && probeMsg.length <= 20;
  quoteRateProbe = !knownFields.destination_country && probeMsg.length >= 3 && !bareDigit && !fillerish;
}

return { json: {
  phone: parsed.phone,
  quoteRateProbe,
  rawMessage: parsed.rawMessage,
  message: parsed.message,
  hasImage: parsed.hasImage,
  unsupportedMedia: parsed.unsupportedMedia || null,
  hasUnsupportedMedia: !!parsed.unsupportedMedia,
  route,
  isFirstContact,
  state,
  context,
  minutesInactive,
  timedOut,
  forcedIntent,
  speculativeExtract,
  trackingExitSignal,
  isPaused,
  trackingFormatValid
} };

// ADDED 2026-08-14 (the product owner Phase 1): never invite an existing customer to
// register. Found live -- a customer with 23 completed orders was asked
// "Don't have an ACME account yet?", which wastes a paid ad click and
// reads badly. Status comes from Customer Lookup, upstream of every reply
// path. Fails OPEN: if the lookup errored or is unavailable we use the
// original new-customer copy, which is exactly today's behaviour and the
// right default for a genuine lead.
const _cust = (function () {
  try {
    const r = $('Customer Lookup').first().json;
    return (r && !r.error) ? r : {};
  } catch (e) { return {}; }
})();
const isRegisteredCustomer = _cust.is_registered === true;
const hasShippedBefore = Number(_cust.order_count || 0) > 0;
const SUCCESS_CTA = isRegisteredCustomer ? "\n\n\ud83d\udca1 Anything else? Just type *menu*." : "\n\n\ud83d\udd17 Don't have an ACME account yet? Register free: https://app.example.com/auth/register\n\ud83d\udca1 Anything else? Just type *menu*.";
const WAIT_CTA_TEXT = isRegisteredCustomer ? "\n\n_While you wait, you can check your orders anytime at example.com._" : "\n\n_While you wait, feel free to explore example.com \u2014 you can create a free account at https://app.example.com/auth/register._";
