  response,
  newContext: { menu: api.menu || null }
} };

// Decide whether this turn should OPEN a structured flow (quote/partner),
// escalate straight to a human, or just resend the menu to a returning
// customer who greeted us. Thresholds are starting points — CLAUDE.md:
// "Confidence thresholds matter... test these hardest before go-live."
const QUOTE_CONF_THRESHOLD = 0.6;
const PARTNER_CONF_THRESHOLD = 0.6;
// FIXED 2026-07-31: a bare "hi" got classified intent=human (confidence
// unknown, but clearly a misfire) deep into a long test session -- likely
// the AI service's own session memory bleeding into classification of an unrelated
// later message. A confidence gate here is cheap insurance against exactly
// that, at the cost of very rarely missing a genuine low-signal human ask
// (which the customer can just repeat/rephrase).
const HUMAN_CONF_THRESHOLD = 0.7;

const api = $input.first().json;
const dm = $('Decision Node').first().json;

const intentName = api.intent && api.intent.name;
const intentConf = (api.intent && typeof api.intent.confidence === 'number') ? api.intent.confidence : 0;

let enterQuote, enterPartner, wantsHuman, isGreeting, isTrackingDigit, isFaqDigit;
let menuRequest = false;

if (dm.forcedIntent) {
  // FIXED 2026-07-31: a digit press is unambiguous and must be the ONLY
  // signal used -- classification of the raw digit text used to be OR'd in
  // alongside it, so pressing "1" (tracking) still opened the Partner flow
  // because the AI service's own classifier (likely biased by this phone's earlier
  // partner-flow history in the session) returned intent=partner for the
  // bare string "1". A digit match must fully bypass classification, not
  // just supplement it.
  enterQuote = dm.forcedIntent === 'quote';
  enterPartner = dm.forcedIntent === 'partner';
  wantsHuman = dm.forcedIntent === 'human';
  isGreeting = false; // a digit press is never treated as a greeting
  isTrackingDigit = dm.forcedIntent === 'tracking';
  isFaqDigit = dm.forcedIntent === 'faq';
} else {
  // FIXED 2026-08-13 (found live): a customer who had JUST completed a
  // partner application replied "Okay" and was dragged into a fresh
  // partner flow and re-asked all eight fields. Same filler-word guard the
  // decision nodes already use for extraction, applied one step earlier --
  // at flow ENTRY, which is where it actually matters. These messages fall
  // through to the normal conversational lane instead.
  const lowSignalText = (dm.rawMessage || '').trim();
  const FILLER_WORDS = /^(hi|hello|hey|hola|sup|yo|thanks|thank you|thx|ok|okay|k|cool|nice|great|good|sure|alright|noted|lol|yes|yeah|yep|no|nope)\b/i;
  const isLowSignal = FILLER_WORDS.test(lowSignalText) && lowSignalText.length <= 20 && !/\d/.test(lowSignalText);

  enterQuote = !isLowSignal && intentName === 'quote' && intentConf >= QUOTE_CONF_THRESHOLD;
  enterPartner = !isLowSignal && intentName === 'partner' && intentConf >= PARTNER_CONF_THRESHOLD;
  // FIXED 2026-08-11: same corroboration rule as the in-flow decision
  // nodes -- see their HUMAN_HINT_WORDS comments. A bare name typed at the
  // main menu must not become a handoff just because classification says so.
  const HUMAN_HINT_WORDS = /\b(human|agent|person|people|someone|somebody|staff|representative|rep|support|team|talk|speak|call|operator|customer (care|service))\b/i;
  wantsHuman = intentName === 'human' && intentConf >= HUMAN_CONF_THRESHOLD && HUMAN_HINT_WORDS.test(dm.rawMessage || '');
  // Only relevant when nothing else above matched -- a returning customer
  // (state already MAIN_MENU, not first contact) who just says hi/hello
  // gets the menu again (brief §5a: "a greeting → send the menu again"),
  // reusing the cached menu[] rather than another firstContact call.
  // ADDED 2026-08-11, FIXED same day after live testing: "menu" is an
  // advertised keyword, so it must be AUTHORITATIVE over classification --
  // the first version only checked it as a fallback after the intent
  // checks, and the AI service (biased by this phone's history) classified a bare
  // "Menu" as partner intent, dragging the customer into Partner Decision
  // whose exit-words bounced them back out with "we can pick the partner
  // sign-up back up any time" -- a flow they were never in. Same lesson as
  // digit presses (see the forcedIntent branch above): a deterministic
  // keyword match fully bypasses classification, never supplements it.
  // Also widened to common natural phrasings after "I need to see the
  // menu" fell through to the unanswered-question fallback live.
  menuRequest = /^\s*(please[,!]?\s+)?(menu|main menu|start over|menu please|the menu|show( me)?( the)? menu|see the menu|i (need|want)( to see)?( the)? menu|(go |take me )?(back )?to (the )?menu)(\s+please)?\s*[.!]*$/i.test((dm.rawMessage || '').trim());
  if (menuRequest) {
    enterQuote = false;
    enterPartner = false;
    wantsHuman = false;
    isGreeting = true;
  } else {
    isGreeting = !enterQuote && !enterPartner && !wantsHuman && intentName === 'greeting';
  }
  isTrackingDigit = false;
  isFaqDigit = false;
}

return { json: {
  ...api,
  _dm: dm,
  _enterQuote: enterQuote,
  _enterPartner: enterPartner,
  _wantsHuman: wantsHuman,
  _isGreeting: isGreeting,
  _menuRequest: menuRequest,
  _isTrackingDigit: isTrackingDigit,
  _isFaqDigit: isFaqDigit
} };

