// backend's recommendation, and only calls out a mismatch when we can SEE
// the fallback is the other mode -- if the response shape is unfamiliar we
// stay quiet rather than adding a confusing note to every quote.
// The raw service name ends with a last-mile descriptor ("...-Self Pick up",
// "...-Delivery to door"). The disclaimer under the quote is the single
// source of truth on the last mile, so the label should not restate it or,
// worse, contradict it.
function displayService(name) {
  return String(name || '')
    .replace(/ *[-–] *(self ?pick ?up|self-collect|collection|delivery to door|door to door|door-to-door) *$/i, '')
    .trim();
