  country: "Sorry, which country are you based in?",
  city: "Sorry, which city?",
  business_type: "Sorry, what line of business is it \u2014 logistics, sourcing, trade, e-commerce, something else?",
  monthly_volume: "Sorry, roughly how much cargo per month?",
  has_warehouse: "Sorry, do you have a local warehouse \u2014 yes or no?"
};

function askText(missingList, fields, justFilled, hasAnswer, isRepeat) {
  const next = ASK_ORDER.filter(function (f) { return missingList.indexOf(f) !== -1; })[0] || missingList[0];
  const done = ASK_ORDER.length - missingList.length;
  const i = (done < 0 ? 0 : done) % ACK_PLAIN.length;

  let ack = '';
  if (justFilled && justFilled.length) {
    const echo = echoOf(justFilled[0], fields[justFilled[0]]);
    ack = echo ? (ACK_WITH_VALUE[i] + echo + '. ') : (ACK_PLAIN[i] + ' ');
  }

  // Offered ONCE, on the opening ask only -- someone who would rather send
  // everything in one go shouldn't be forced through a question at a time.
  let tail = '';
  if (!hasAnswer && (!justFilled || !justFilled.length) && missingList.length >= 4) {
    tail = "\n\n_Or send it all in one message if that's easier._";
  }
  // Nothing was captured this turn and we already asked -- rephrase.
  if (isRepeat && REASK[next]) return REASK[next];

  return ack + FIELD_ASK[next] + tail + '';
}

// Duplicated in Partner Deterministic Handler (separate n8n Code node, no
// shared scope) -- keep the two in sync if this changes. Field order follows
// the PRD §5.2 numbering.
function summary(f) {
  const lines = [
    "Here's what I've got for your partner application:",
    '\u2022 Name: ' + f.contact_name,
    '\u2022 WhatsApp number: ' + f.phone,
    '\u2022 Email: ' + f.email,
    '\u2022 Nationality: ' + (f.nationality || '(not yet collected)'),
    '\u2022 Current country/city: ' + f.country + (f.city ? (', ' + f.city) : ''),
    '\u2022 Primary operating market: ' + (f.primary_operating_market || '(not yet collected)'),
    '\u2022 Business/company name: ' + f.business_name,
    '\u2022 Business type: ' + f.business_type,
    '\u2022 Monthly volume: ' + f.monthly_volume,
    '\u2022 Existing customer resources: ' + (f.existing_customer_resources || '(not yet collected)'),
    '\u2022 Local warehouse: ' + f.has_warehouse,
    '\u2022 Local delivery capability: ' + (f.local_delivery_capability || '(not yet collected)'),
    '\u2022 COD capability: ' + (f.cod_capability || '(not yet collected)'),
    '\u2022 Services requested: ' + (f.services_requested || '(not yet collected)')
  ];
  if (f.additional_information) lines.push('\u2022 Additional info: ' + f.additional_information);
  lines.push('\nShall I go ahead and submit this? Reply *yes* to confirm, or tell me what to change.');
  return lines.join('\n');
}

function ctx(f, attempts, extra) {
  // FIXED 2026-07-31: this used to drop the cached menu[] on every progress
  // write, not just at reset time -- carry it forward here too.
  return JSON.stringify(Object.assign({ flow: 'partner', fields: f, askAttempts: attempts, menu: (dm.context && dm.context.menu) || null }, extra || {}));
}

if (priorState === 'PARTNER_CONFIRMING') {
  const fieldsChanged = !isFillerMessage && Object.keys(extractedFields).some(k =>
    extractedFields[k] !== null && extractedFields[k] !== undefined && extractedFields[k] !== priorFields[k]
  );
  if (missing.length > 0) {
    return { json: { phone, action: 'ask_missing', escalate: false, newState: 'PARTNER_COLLECTING', fields, askAttempts: {}, context: ctx(fields, {}), message: sideAnswer + askText(missing, fields, justFilled, !!sideAnswer, isRepeatAsk) } };
  }
  if (fieldsChanged) {
    return { json: { phone, action: 'confirm_summary', escalate: false, newState: 'PARTNER_CONFIRMING', fields, askAttempts: {}, context: ctx(fields, {}), message: sideAnswer + "Updated \u2014 here's the new summary:\n\n" + summary(fields) } };
  }
  // Affirmation was already handled above (before the merge). Anything else
  // reaching here is ambiguous -- re-show the summary rather than guess.
  return { json: { phone, action: 'confirm_summary', escalate: false, newState: 'PARTNER_CONFIRMING', fields, askAttempts: {}, context: ctx(fields, {}), message: sideAnswer + summary(fields) } };
}

if (missing.length === 0) {
  // All AI-extractable required fields are done -- hand off to the
  // deterministic phase for the PRD fields the AI service can't extract at all.
  const DQ_FIRST_QUESTION = "What's your nationality?";
  return { json: {
    phone, action: 'ask_missing', escalate: false, newState: 'PARTNER_COLLECTING', fields, askAttempts: {},
    context: ctx(fields, {}, { phase: 'deterministic', dqIndex: 0, dqAttempts: 0 }),
    message: sideAnswer + "Great, that's the main details covered! A few more quick ones:\n\n" + DQ_FIRST_QUESTION
  } };
}

// FIXED 2026-08-01 (same fix as Quote Decision, found by external code
// review): a single stall counter that only advances when NO previously-
// missing field got filled in this turn, resetting to 0 on any progress --
// otherwise a cooperative customer answering one field per message got
// escalated purely because other fields' own counters kept climbing.
const priorMissing = REQUIRED_FIELDS.filter(f => priorFields[f] === null || priorFields[f] === undefined || priorFields[f] === '');
const stillMissingSet = new Set(missing);
const progressMade = priorMissing.some(f => !stillMissingSet.has(f));
let stallCount = isFreshEntry ? 0 : (priorAskAttempts.__stall || 0);
if (!isFreshEntry) stallCount = progressMade ? 0 : stallCount + 1;
const askAttempts = { __stall: stallCount };
const stalled = stallCount >= MAX_ASK_ATTEMPTS;

if (stalled) {
  return { json: {
    phone, action: 'handoff', escalate: true, fields, missing,
    message: "Let's get you sorted a different way \u2014 I'll have one of our team follow up and finish your partner application with you directly. Someone will be in touch shortly. \ud83d\ude4f" + WAIT_CTA_TEXT + ""
  } };
}

return { json: { phone, action: 'ask_missing', escalate: false, newState: 'PARTNER_COLLECTING', fields, askAttempts, context: ctx(fields, askAttempts), message: sideAnswer + askText(missing, fields, justFilled, !!sideAnswer, isRepeatAsk) + (((isFreshEntry && !sideAnswer) || stallCount >= 2) ? NAV_HINT : '') } };

