// Partner Lead No. -- n8n mints this (brief §7: "Partner Lead No. (ours to
// generate)"), unlike Quote's quote_no which is backend-minted. No external
// call needed.
const qd = $('Is Partner Submit?').first().json;
function randSuffix(n) {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no ambiguous chars
  let s = '';
  for (let i = 0; i < n; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return s;
}
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const datePart = now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate());
const timePart = pad(now.getUTCHours()) + pad(now.getUTCMinutes()) + pad(now.getUTCSeconds());
const leadNo = 'PTR-' + datePart + '-' + timePart + '-' + randSuffix(4);
return { json: { phone: qd.phone, fields: qd.fields, leadNo } };

// ADDED 2026-08-14 (the product owner Phase 1): never invite an existing customer to
// register. Found live -- a customer with 23 completed orders was asked
// "Don't have an ACME account yet?", which wastes a paid ad click and
// reads badly. Status comes from Customer Lookup, upstream of every reply
// path. Fails OPEN: if the lookup errored or is unavailable we use the
// original new-customer copy, which is exactly today's behaviour and the
// right default for a genuine lead.
const _cust = (function () {
  try {
    const r = $('Customer Lookup').first().json;
    return (r && !r.error) ? r : {};
