const WAIT_CTA_TEXT = isRegisteredCustomer ? "\n\n_While you wait, you can check your orders anytime at example.com._" : "\n\n_While you wait, feel free to explore example.com \u2014 you can create a free account at https://app.example.com/auth/register._";
const FAQ_CTA_TEXT = isRegisteredCustomer ? "\n\n\ud83d\udca1 Type *menu* for more options." : "\n\n\ud83d\udd17 New to ACME? Register free: https://app.example.com/auth/register\n\ud83d\udca1 Type *menu* for more options.";

// PRD §5.4 exact wording -- the fixed successful-registration reply.
const m = $('Mint Partner Lead No.').first().json;
const f = m.fields;
const message = "Thank you for your interest in joining the ACME Partner Network. Your information has been successfully registered. Our partnership team will review it and contact you through WhatsApp.\n\nReference: " + m.leadNo + SUCCESS_CTA;
