// Decide what an outbound message means.
const src = $('Parse Message').first().json;
const items = $input.all().map(i => i.json);
// FIXED 2026-08-13 (caught in review before shipping): a FAILED lookup used
// to be indistinguishable from "no match", so a Postgres blip made the bot
// classify its OWN message as a teammate takeover and silence itself for
// hours on a live customer -- the single worst failure this feature could
// have. An inconclusive lookup must now do nothing at all.
const lookupFailed = items.some(r => r && r.error);
const rows = items.filter(r => r && !r.error);
const weSentIt = rows.some(r => r && (r.hit === 1 || r.hit === '1'));

const text = (src.rawMessage || '').trim();
// Manual overrides a teammate can type in the chat itself.
const isResume = /^#resume\b/i.test(text);
const isPause = /^#pause\b/i.test(text);

// FIXED 2026-08-13 (found in post-build audit): OTHER ACME systems send
// from this same WhatsApp number -- the invoice notifications are visible
// in the bot account's own chat list ("*ACME* Hi <name>, Invoice
// *INV-...*"). Those arrive as fromMe with no recorded hash, so every
// invoice blast would have silenced the bot for that customer for 6 hours.
// Known machine-sent formats are never treated as a human takeover. Add
// patterns here if another system starts sharing the number.
const SYSTEM_PATTERNS = [
  /^\*ACME\*/i,               // invoice/notification blasts open with "*ACME*"
  /\bInvoice\s+\*?INV-\d/i     // and/or carry an invoice number
];
const isSystemMessage = SYSTEM_PATTERNS.some(p => p.test(text));

let action = 'none';
if (isResume) {
  action = 'resume';
} else if (isPause) {
  // Explicit override always honoured, even if the lookup was inconclusive.
  action = 'pause';
} else if (lookupFailed || isSystemMessage) {
  // lookupFailed: cannot tell whose message this is -- stay out of it.
  // isSystemMessage: a sibling system (invoices) sent it, not a teammate.
  // Either way the worst case is the bot keeps talking -- today's
  // behaviour, not a regression.
  action = 'none';
} else if (!weSentIt) {
  action = 'pause';
}

const PAUSE_HOURS = 6;
const until = action === 'resume'
  ? new Date(Date.now() - 1000)            // already expired = un-paused
  : new Date(Date.now() + PAUSE_HOURS * 3600 * 1000);

return { json: {
  phone: src.phone,
  action,
  isPause,
  isResume,
  pausedUntil: until.toISOString(),
  reason: action === 'resume' ? 'manual #resume' : (isPause ? 'manual #pause' : 'teammate replied by hand'),
  shouldWrite: action !== 'none'
} };

// A teammate is handling this customer by hand. Their message has still
// been de-duplicated and their session clock still ticks -- we simply do
// not reply. The pause lapses on its own (6h since the teammate's last
// message), or immediately if they type #resume in the chat.
return { json: { dropped: 'paused', phone: $json.phone } };
